// Spatiotemporal blue-noise sampling for the test bed's 1-spp signals (`sampling=blue`,
// the default; `sampling=white` keeps the original PCG white noise). Renderers that feed
// real-time denoisers sample with per-pixel blue noise animated per frame
// (renderer contract, docs/research/rt-denoiser/sources/shadows-specular.md: RTG II
// ch. 24 §24.7.2, Wolfe 2021), and denoisers behave differently on it, so M1 numbers
// and the native comparison use it. All public methods:
//
//   mask      one 128x128 void-and-cluster dither array (Ulichney 1993), generated by
//             gen-bluenoise.mjs into bluenoise-128.bin (uint16 ranks).
//   per dim   each sample dimension d reads the mask at its own fixed toroidal shift
//             (shifts from the R2 sequence, so they are far apart and different
//             dimensions are spatially decorrelated), then adds a constant
//             Cranley-Patterson rotation rot_d (Cranley & Patterson 1976) so no two
//             dimensions share values either.
//   per frame value += frame * alpha_d (mod 1): the additive recurrence of RTG II §24.7.2
//             (golden ratio for one scalar), generalized to the R_n sequence of
//             M. Roberts, "The Unreasonable Effectiveness of Quasirandom Sequences"
//             (2018) for an n-dimensional sample: alpha_i = 1 / phi_n^i, phi_n the real
//             root of x^(n+1) = x + 1. A pixel's samples over time then form an
//             n-D low-discrepancy sequence (a golden-ratio step on every dimension of a
//             2D sample would put them on a line), and each frame stays blue in screen
//             space (a constant shift of a blue mask mod 1).
//
// The diffuse and specular signals use 4 dimensions each (2 for the bounce direction, 2
// for the light sample at the secondary hit) with R4; shadows use 2 with R2.
// Everything is fixed-point u32 arithmetic in the shader (exact wrap-around mod 1).
// References are unchanged (stratified grid + white noise, converged).

export const BN_SIZE = 128;

/** phi_n: the real root of x^(n+1) = x + 1 (n = 1 golden ratio, n = 2 plastic number) */
function phi(n: number) {
  let x = 2;
  for (let i = 0; i < 64; i++) x = Math.pow(1 + x, 1 / (n + 1));
  return x;
}
const fx32 = (f: number) => Math.round((f - Math.floor(f)) * 2 ** 32) >>> 0;
/** R_n per-frame increments as u32 fixed point */
const alphas = (n: number) => Array.from({ length: n }, (_, i) => fx32(1 / phi(n) ** (i + 1)));

/** sample dimensions: [diffuse 0..3, specular 4..7, shadows 8..9] */
const DIM_ALPHA = [...alphas(4), ...alphas(4), ...alphas(2)];
const DIMS = DIM_ALPHA.length;
const R2 = alphas(2).map((a) => a / 2 ** 32);
/** toroidal mask shift per dimension (R2 points scaled to the mask) */
const DIM_SHIFT = Array.from({ length: DIMS }, (_, d) =>
  [0, 1].map((k) => Math.floor(((0.5 + (d + 1) * R2[k]) % 1) * BN_SIZE)));
/** Cranley-Patterson rotation per dimension (fixed, irrational multiples) */
const DIM_ROT = Array.from({ length: DIMS }, (_, d) => fx32(0.5 + (d + 1) * Math.SQRT2));

const u32s = (xs: number[]) => xs.map((x) => `${x >>> 0}u`).join(', ');

/** WGSL: `bn` storage buffer at `binding` + bnXi(pix, frame, dim) in [0, 1) */
export const bnWgsl = (binding: number) => /* wgsl */ `
@group(0) @binding(${binding}) var<storage, read> bn: array<u32>;
const BN_SIZE: u32 = ${BN_SIZE}u;
const BN_ALPHA = array<u32, ${DIMS}>(${u32s(DIM_ALPHA)});
const BN_ROT = array<u32, ${DIMS}>(${u32s(DIM_ROT)});
const BN_SHIFT = array<vec2u, ${DIMS}>(${DIM_SHIFT.map(([x, y]) => `vec2u(${x}u, ${y}u)`).join(', ')});
fn bnXi(pix: vec2u, frame: u32, dim: u32) -> f32 {
  let q = (pix + BN_SHIFT[dim]) % BN_SIZE;
  let rank = bn[q.y * BN_SIZE + q.x];                       // 0 .. BN_SIZE^2 - 1
  // rank -> [0, 1) as u32 fixed point (cell centre), + rotation + frame * alpha (mod 2^32)
  let v = (rank << 18u) + (1u << 17u) + BN_ROT[dim] + frame * BN_ALPHA[dim];
  return f32(v >> 8u) / 16777216.0;
}
fn bn2(pix: vec2u, frame: u32, dim: u32) -> vec2f {
  return vec2f(bnXi(pix, frame, dim), bnXi(pix, frame, dim + 1u));
}
`;

/** Load the mask (ranks as u32, one per texel) into a storage buffer. */
export async function loadBlueNoise(device: GPUDevice): Promise<GPUBuffer> {
  const res = await fetch(new URL('./bluenoise-128.bin', import.meta.url));
  if (!res.ok) throw new Error(`blue-noise mask: HTTP ${res.status}`);
  const ranks = new Uint16Array(await res.arrayBuffer());
  if (ranks.length !== BN_SIZE * BN_SIZE) throw new Error(`blue-noise mask: ${ranks.length} texels, expected ${BN_SIZE * BN_SIZE}`);
  const buf = device.createBuffer({ label: 'rt blue noise', size: ranks.length * 4, usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST });
  device.queue.writeBuffer(buf, 0, Uint32Array.from(ranks));
  return buf;
}
